//
// Golden assembly tests: the EASy68K-Qt assembler must produce the same
// S-records (.s68) and listing (.l68) as the ORIGINAL EASy68K assembler.
// The golden files are generated by the reference oracle built from the
// original sources (tools/reference/regenerate_golden.sh), not by the port.
//
// Parity gaps still being fixed are listed in data/golden/asm/known_failures.txt
// ("<name> s68" / "<name> l68"). A listed case that mismatches is reported as
// skipped; a listed case that now matches fails, so the list is kept current.

#include <gtest/gtest.h>

#include <filesystem>
#include <fstream>
#include <set>
#include <sstream>
#include <string>

#include "easym68k/asm/assembler.h"

namespace easym68k::asm_ {
namespace {

std::string FindGoldenDir() {
  std::filesystem::path p = std::filesystem::current_path();
  for (int i = 0; i < 5; ++i) {
    if (std::filesystem::exists(p / "data" / "golden" / "asm")) {
      return (p / "data" / "golden" / "asm").string();
    }
    p = p.parent_path();
  }
  return "data/golden/asm";
}

std::string ReadFile(const std::string& path) {
  std::ifstream f(path, std::ios::in | std::ios::binary);
  if (!f.is_open()) {
    return "";
  }
  std::ostringstream ss;
  ss << f.rdbuf();
  return ss.str();
}

// The original wrote Windows text files; compare independent of CR LF / LF.
std::string StripCr(const std::string& s) {
  std::string out;
  out.reserve(s.size());
  for (char c : s)
    if (c != '\r')
      out.push_back(c);
  return out;
}

const std::set<std::string>& KnownFailures() {
  static const std::set<std::string> known = [] {
    std::set<std::string> k;
    std::istringstream in(StripCr(ReadFile(FindGoldenDir() + "/known_failures.txt")));
    for (std::string line; std::getline(in, line);) {
      if (line.empty() || line[0] == '#')
        continue;
      k.insert(line.substr(0, line.find_first_of(" \t#", line.find(' ') + 1)));
    }
    return k;
  }();
  return known;
}

void CheckOutput(const std::string& test_name, const char* kind, const std::string& generated,
                 const std::string& golden) {
  bool known = KnownFailures().count(test_name + " " + kind) != 0;
  bool match = StripCr(generated) == StripCr(golden);
  if (known && match) {
    ADD_FAILURE() << test_name << " " << kind
                  << " now matches the original; remove it from known_failures.txt";
  } else if (!known) {
    EXPECT_EQ(StripCr(generated), StripCr(golden)) << kind << " mismatch for " << test_name;
  }
}

class GoldenAssemblyTest : public ::testing::TestWithParam<std::string> {
 protected:
  Assembler assembler_;
};

TEST_P(GoldenAssemblyTest, MatchesOriginalAssembler) {
  std::string test_name = GetParam();
  std::string golden_dir = FindGoldenDir();
  std::string source = StripCr(ReadFile(golden_dir + "/" + test_name + ".x68"));
  ASSERT_FALSE(source.empty()) << "Failed to read golden source: " << test_name;
  std::string golden_s68 = ReadFile(golden_dir + "/" + test_name + ".s68");
  std::string golden_l68 = ReadFile(golden_dir + "/" + test_name + ".l68");
  ASSERT_FALSE(golden_s68.empty()) << "Missing golden .s68 (tools/reference/regenerate_golden.sh)";
  ASSERT_FALSE(golden_l68.empty()) << "Missing golden .l68 (tools/reference/regenerate_golden.sh)";

  assembler_.ConfigureListing(test_name + ".x68", "");
  auto result = assembler_.Assemble(source);
  ASSERT_TRUE(result.success) << "Assembly failed for " << test_name << "\n"
                              << (result.errors.empty() ? "" : result.errors[0].message);

  CheckOutput(test_name, "s68", result.srecord, golden_s68);
  CheckOutput(test_name, "l68", assembler_.GetListing(), golden_l68);

  bool any_known =
      KnownFailures().count(test_name + " s68") || KnownFailures().count(test_name + " l68");
  if (any_known && !HasFailure())
    GTEST_SKIP() << "known parity gap(s) listed in known_failures.txt";
}

INSTANTIATE_TEST_SUITE_P(GoldenAssemblySuite, GoldenAssemblyTest,
                         ::testing::Values("01_nop", "02_arithmetic", "03_logic", "04_shifts",
                                           "05_moves", "06_branches", "07_comparisons", "08_movem",
                                           "09_stack", "10_directives_dc", "11_directives_ds",
                                           "12_directives_equ", "13_directives_org",
                                           "14_macro_simple", "15_macro_params", "16_macro_narg",
                                           "17_macro_continuation", "18_conditional_assembly",
                                           "19_structured_if", "20_structured_loop",
                                           "21_memory_map"));

}  // namespace
}  // namespace easym68k::asm_
